pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val1, uint256 _val2) internal {
        vm.assume(true);
        bool reverted1;
        try c.SetMinSum(_val1) { reverted1 = false; } catch { reverted1 = true; }
        bool reverted2;
        try c.SetMinSum(_val2) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(!reverted1 && !reverted2);
    }

    function testFuzz_run(uint256 _val1, uint256 _val2) public {
        _run(_val1, _val2);
    }

    receive() external payable {}
}
